<?php
$bookings = q("SELECT b.*,u.nombre AS cliente,u.apellido,s.nombre AS servicio,h.fecha,h.hora_inicio,h.hora_fin FROM reservas b JOIN usuarios u ON u.id=b.cliente_id JOIN servicios s ON s.id=b.servicio_id JOIN horarios h ON h.id=b.horario_id ORDER BY b.creada_en DESC,b.id DESC")->fetchAll();
?>
<main class="container section"><a class="back" href="<?= url('admin') ?>">← Volver a administración</a><span class="eyebrow">SEGUIMIENTO</span><h1>Reservas de clientes</h1><p class="lead">Confirma solicitudes, marca atenciones realizadas o cancela citas.</p>
<?php foreach ($bookings as $b): ?><article class="booking"><div class="booking-main"><span class="pill status-<?= e(strtolower($b['estado'])) ?>"><?= e($b['estado']) ?></span><h2><?= e($b['servicio']) ?></h2><p><?= e($b['fecha']) ?> · <?= e(substr($b['hora_inicio'],0,5)) ?>–<?= e(substr($b['hora_fin'],0,5)) ?> · <?= e($b['cliente'].' '.$b['apellido']) ?></p><small>Reserva #<?= e($b['id']) ?> · Actualizada <?= e($b['actualizada_en']) ?></small></div><div class="booking-actions">
<?php if (in_array($b['estado'],['PENDIENTE','CONFIRMADA'],true)): ?><form class="inline" method="post" action="<?= url('admin-status') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($b['id']) ?>"><input type="hidden" name="estado" value="<?= $b['estado']==='PENDIENTE'?'CONFIRMADA':'REALIZADA' ?>"><button class="button small-button" type="submit"><?= $b['estado']==='PENDIENTE'?'Confirmar':'Marcar realizada' ?></button></form>
<form class="inline" method="post" action="<?= url('admin-status') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($b['id']) ?>"><input type="hidden" name="estado" value="CANCELADA"><button class="button-outline" data-confirm="¿Cancelar esta reserva?" type="submit">Cancelar</button></form><?php endif; ?>
</div></article><?php endforeach; ?><?php if (!$bookings): ?><p class="empty">No hay reservas todavía.</p><?php endif; ?></main>
